                bot_8 = br
                break

        # No 8-rows nearby: skip
        if top_8 is None and bot_8 is None:
            continue

        # Apply pattern rules based on nearest 8-rows
        if top_8 is None:
            # Only 8 below (adjacent case)
            bot_holes = get_holes(grid[bot_8])
            if bot_holes:
                # Rows 1 fills between min and max of bot-holes
